<?php
require __DIR__.'/includes/bootstrap.php';
$id=(int)($_GET['id']??0);$plate=trim((string)($_GET['plate']??''));
if($id>0){$s=$pdo->prepare('SELECT v.*,u.full_name AS registrar_name FROM vehicles v LEFT JOIN users u ON u.id=v.registered_by WHERE v.id=?');$s->execute([$id]);}elseif($plate!==''){$s=$pdo->prepare('SELECT v.*,u.full_name AS registrar_name FROM vehicles v LEFT JOIN users u ON u.id=v.registered_by WHERE REPLACE(UPPER(v.plate)," ","")=REPLACE(UPPER(?)," ","")');$s->execute([$plate]);}else{redirect('index.php');}
$v=$s->fetch();if(!$v){http_response_code(404);$page_title='Автомобиль не найден';include __DIR__.'/includes/header.php';echo '<section class="panel empty-state"><div class="empty-icon">⌕</div><h1>Автомобиль не найден</h1><p>В реестре нет транспортного средства с такими данными.</p><a class="btn btn-primary" href="index.php">Вернуться к поиску</a></section>';include __DIR__.'/includes/footer.php';exit;}
$page_title=$v['make'].' '.$v['model'];
$ownerAccess=is_logged_in() && (has_role(['inspector','officer','admin']) || (int)current_user()['id']===(int)$v['owner_user_id'] || mb_strtolower(current_user()['email'])===mb_strtolower($v['owner_email']));
$s=$pdo->prepare('SELECT * FROM vehicle_photos WHERE vehicle_id=? ORDER BY created_at DESC');$s->execute([$v['id']]);$photos=$s->fetchAll();
$s=$pdo->prepare('SELECT h.*,u.full_name FROM vehicle_history h LEFT JOIN users u ON u.id=h.created_by WHERE h.vehicle_id=? ORDER BY h.event_date DESC,h.id DESC');$s->execute([$v['id']]);$history=$s->fetchAll();
$s=$pdo->prepare('SELECT id,external_ref,title,amount,due_date,status,bank_status FROM fines WHERE vehicle_id=? ORDER BY created_at DESC LIMIT 20');$s->execute([$v['id']]);$fines=$ownerAccess?$s->fetchAll():[];
include __DIR__.'/includes/header.php';
?>
<section class="panel vehicle-top"><div><span class="eyebrow">Карточка транспортного средства</span><div class="vehicle-title"><h1><?= e($v['make'].' '.$v['model']) ?></h1><span class="badge <?= $v['status']==='active'?'badge-green':'badge-yellow' ?>"><?= e(status_label($v['status'])) ?></span></div><div class="vehicle-subtitle">Год выпуска: <?= e($v['year']) ?> · Цвет: <?= e($v['color']?:'не указан') ?> · Добавлен <?= e(date('d.m.Y',strtotime($v['created_at']))) ?></div></div><div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap"><span class="license-plate"><?= e($v['plate']) ?></span><?php if(has_role(['officer','admin'])): ?><a class="btn btn-primary" href="issue_fine.php?vehicle_id=<?= (int)$v['id'] ?>">＋ Оформить штраф</a><?php endif; ?></div></section>
<div class="detail-grid"><div><section class="panel panel-pad"><div class="section-head"><div><h2>Основные сведения</h2><p class="muted tiny">Идентификационные данные автомобиля</p></div><?php if($ownerAccess): ?><span class="badge badge-blue">Служебный доступ</span><?php endif; ?></div><div class="spec-grid"><div class="spec"><span>Государственный номер</span><strong><?= e($v['plate']) ?></strong></div><div class="spec"><span>VIN</span><strong><?= e($v['vin']) ?></strong></div><div class="spec"><span>Марка / модель</span><strong><?= e($v['make'].' '.$v['model']) ?></strong></div><div class="spec"><span>Год выпуска</span><strong><?= e($v['year']) ?></strong></div><div class="spec"><span>Цвет кузова</span><strong><?= e($v['color']?:'Не указан') ?></strong></div><div class="spec"><span>Дата регистрации</span><strong><?= e($v['registered_at']?date('d.m.Y',strtotime($v['registered_at'])):'—') ?></strong></div><?php if($ownerAccess): ?><div class="spec"><span>Владелец</span><strong><?= e($v['owner_name']) ?></strong></div><div class="spec"><span>Email владельца</span><strong><?= e($v['owner_email']) ?></strong></div><?php endif; ?></div><?php if(!$ownerAccess): ?><div class="help-box" style="margin-top:17px">Для защиты персональных данных ФИО, email владельца и сведения о начислениях видны только владельцу автомобиля и уполномоченным сотрудникам.</div><?php endif; ?><?php if($v['notes'] && $ownerAccess): ?><div class="divider"></div><h3>Служебная заметка</h3><p class="muted tiny"><?= nl2br(e($v['notes'])) ?></p><?php endif; ?></section>
<section class="panel" style="margin-top:17px"><div class="panel-header"><h2>История автомобиля</h2><p>Регистрационные действия и отметки</p></div><div class="panel-body"><div class="timeline"><?php if($history): foreach($history as $h): ?><div class="timeline-item"><span class="timeline-dot"></span><div><strong><?= e($h['title']) ?></strong><p><?= e($h['description']?:'Событие внесено в реестр.') ?></p><p><?= e(date('d.m.Y',strtotime($h['event_date']))) ?><?php if($ownerAccess && $h['full_name']): ?> · <?= e($h['full_name']) ?><?php endif; ?></p></div></div><?php endforeach; else: ?><p class="muted tiny">История пока не содержит событий.</p><?php endif; ?></div></div></section>
<?php if($ownerAccess): ?><section class="panel" style="margin-top:17px"><div class="panel-header"><h2>Начисления по автомобилю</h2><p>Информация о штрафах доступна владельцу и сотрудникам</p></div><?php if($fines): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Постановление</th><th>Сумма</th><th>Срок</th><th>Статус</th><th>Банк</th></tr></thead><tbody><?php foreach($fines as $f): ?><tr><td><strong><?= e($f['external_ref']) ?></strong><br><span class="muted tiny"><?= e($f['title']) ?></span></td><td><?= money($f['amount']) ?></td><td><?= e($f['due_date']) ?></td><td><?= e(status_label($f['status'])) ?></td><td><?= e(status_label($f['bank_status'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="panel-body"><p class="muted tiny">Начислений по этому автомобилю нет.</p></div><?php endif; ?></section><?php endif; ?></div>
<aside><section class="panel panel-pad"><div class="section-head"><div><h2>Фотографии</h2><p class="muted tiny">Фотографии транспортного средства</p></div><span class="tag"><?= count($photos) ?> фото</span></div><?php if($photos): foreach($photos as $photo): ?><div class="photo-frame" style="margin-bottom:10px"><img src="<?= e($photo['file_path']) ?>" alt="Фото <?= e($v['make'].' '.$v['model']) ?>"></div><?php if($photo['caption']): ?><p class="muted tiny"><?= e($photo['caption']) ?></p><?php endif; ?><?php endforeach; else: ?><div class="photo-frame"><div class="photo-placeholder"><span>▧</span>Фотографии пока не добавлены</div></div><?php endif; ?><?php if($ownerAccess && !has_role('inspector')): ?><div class="divider"></div><form action="upload_photo.php" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="vehicle_id" value="<?= (int)$v['id'] ?>"><div class="field"><label for="photo">Добавить фото</label><input id="photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp" required><small>JPG / PNG / WEBP, до 5 МБ</small></div><div class="field"><label for="caption">Подпись (необязательно)</label><input id="caption" name="caption" maxlength="180" placeholder="Вид спереди"></div><button class="btn btn-ghost" type="submit">Загрузить фотографию</button></form><?php endif; ?></section><section class="panel panel-pad" style="margin-top:17px"><h2>Регистрационные данные</h2><div class="summary-row"><span>Дата регистрации</span><strong><?= e($v['registered_at']?date('d.m.Y',strtotime($v['registered_at'])):'—') ?></strong></div><div class="summary-row"><span>Запись добавил</span><strong><?= e($ownerAccess?($v['registrar_name']?:'Система'):'Сотрудник ГИБДД') ?></strong></div><div class="summary-row"><span>Номер региона</span><strong>200</strong></div><?php if(has_role(['officer','admin'])): ?><div class="divider"></div><a class="btn btn-primary" style="width:100%" href="issue_fine.php?vehicle_id=<?= (int)$v['id'] ?>">Оформить штраф</a><?php endif; ?></section></aside></div>
<?php include __DIR__.'/includes/footer.php'; ?>
